import {ANALYTICS_POLICY_VERSION,ANALYTICS_EXPORT_FORMAT} from './analytics-policy.js';
let key='';const $=s=>document.querySelector(s);const api=async path=>{const r=await fetch(path,{headers:{Authorization:'Bearer '+key},cache:'no-store'});if(!r.ok)throw new Error('접근키 또는 서버 연결을 확인해 주세요.');return r.json();};
$('#login').addEventListener('submit',async event=>{event.preventDefault();key=$('#key').value;try{const data=await api('/api/admin/summary');$('#summary').replaceChildren();const p=document.createElement('p');p.textContent=`실행 ${data.runs}회 · 월별 기록 ${data.monthlyRecords}개`;$('#summary').append(p);if(Array.isArray(data.editions)){const edition=document.createElement('p');edition.textContent=data.editions.map(row=>(row.edition==='ko'?'한국판':row.edition==='en'?'북미판':'구분 오류')+' '+row.runs+'회').join(' · ');$('#summary').append(edition);}const table=document.createElement('table');for(const ending of data.endings){const row=document.createElement('tr');for(const value of [ending.ending,ending.runs]){const cell=document.createElement('td');cell.textContent=value;row.append(cell);}table.append(row);}$('#summary').append(table);$('#export').hidden=false;$('#status').textContent='통계를 불러왔습니다.';}catch(error){$('#status').textContent=error.message;}});
$('#export').addEventListener('click',async()=>{try{const data=await api('/api/admin/export'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='professor-maker-anonymous-records.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(error){$('#status').textContent=error.message;}});

$('#import').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>10000000)throw new Error('10 MB 이하 파일을 사용하세요.');const data=JSON.parse(await file.text());if(data.format!==ANALYTICS_EXPORT_FORMAT||data.consent!==ANALYTICS_POLICY_VERSION||!Array.isArray(data.runs)||data.runs.length>100)throw new Error('익명 분석 파일 형식을 확인해 주세요.');if(!data.runs.every(run=>run&&typeof run==='object'&&['ko','en'].includes(run.profile?.edition)))throw new Error('한국판·북미판 구분이 있는 새 동의 버전 파일을 사용하세요.');let count=0;for(const run of data.runs){const response=await fetch('/api/admin/import',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+key},body:JSON.stringify({...run,consent:data.consent})});if(!response.ok)throw new Error('접근키 또는 기록 형식을 확인해 주세요.');count+=(await response.json()).imported;}$('#status').textContent=count+'개의 월별 기록을 DB에 적재했습니다.';}catch(error){$('#status').textContent=error.message;}});
